'use client';

import { useEffect, useRef } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { toast } from 'sonner'; // or whatever toast import already exists in this file

export function ConnectReturnHandler() {
  const params = useSearchParams();
  const router = useRouter();
  const handledRef = useRef(false);

  useEffect(() => {
    const onboarding = params.get('onboarding');
    const type = params.get('type');
    if (handledRef.current) return;
    if (onboarding !== 'complete') return;
    if (type !== 'studio' && type !== 'artist') return;

    handledRef.current = true;
    let cancelled = false;

    (async () => {
      try {
        const res = await fetch(`/api/billing/connect/status?type=${encodeURIComponent(type)}`);
        if (!res.ok || cancelled) return;
        const status = await res.json();
        if (cancelled) return;

        if (status?.onboarding_status === 'active') {
          toast.success('Verification submitted.', {
            description: 'Stripe will email you when your account is fully ready.',
          });
        } else if (status?.onboarding_status === 'pending') {
          toast('Submitted.', {
            description: 'Stripe is still verifying — refresh in a minute.',
          });
        }
        // No toast for restricted/rejected/null — page banner handles those.

        router.refresh();
      } finally {
        // Always clean URL after handling
        if (typeof window !== 'undefined') {
          window.history.replaceState({}, '', window.location.pathname);
        }
      }
    })();

    return () => { cancelled = true; };
  }, [params, router]);

  return null;
}
```

Match existing toast import — if the file imports from `@/components/ui/sonner` keep that. If from `sonner` directly, keep that.

