'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { Loader2, Wallet, Landmark, Shield } from 'lucide-react'
import { Button } from '@/components/ui/button'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { cn } from '@/lib/utils'

const UNLOCK_ITEMS = [
  {
    icon: Landmark,
    title: 'Deposit pool — atomic settlement',
    description: 'Deposits collected at booking automatically drawn down on the session charge. Zero manual reconciliation.',
  },
  {
    icon: Wallet,
    title: '70/30 commission splits',
    description: 'Artist and studio shares settle separately on every charge. No end-of-week spreadsheet exports.',
  },
  {
    icon: Shield,
    title: 'Dispute defense pack — auto-bundling',
    description: 'Evidence assembled from booking history, consent forms, and photos. Submitted to Stripe automatically.',
  },
]

const COUNTRY_OPTIONS: { value: string; label: string }[] = [
  { value: 'US', label: 'United States' },
  { value: 'GB', label: 'United Kingdom' },
  { value: 'CA', label: 'Canada' },
  { value: 'AU', label: 'Australia' },
  { value: 'DE', label: 'Germany' },
  { value: 'FR', label: 'France' },
  { value: 'NL', label: 'Netherlands' },
  { value: 'IE', label: 'Ireland' },
  { value: 'ES', label: 'Spain' },
  { value: 'IT', label: 'Italy' },
]

interface Props {
  studioCountry: string | null
}

export function ConnectOnboardingCallToAction({ studioCountry }: Props) {
  const [modalOpen, setModalOpen] = useState(false)
  const [selectedCountry, setSelectedCountry] = useState<string>(studioCountry ?? 'US')
  const [busy, setBusy] = useState(false)

  async function handleEnable(country: string) {
    setBusy(true)
    try {
      const res = await fetch('/api/billing/connect/onboard', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type: 'studio', country }),
      })

      if (!res.ok) {
        const json = await res.json() as { error?: string; message?: string }
        toast.error(json.message ?? json.error ?? 'Could not start Stripe onboarding. Try again.')
        return
      }

      const json = await res.json() as { url?: string; error?: string }
      if (!json.url) {
        toast.error('No onboarding link returned. Contact support if this persists.')
        return
      }

      window.location.assign(json.url)
    } catch {
      toast.error('Connection error. Check your network and try again.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="space-y-8">
      {/* Editorial serif moment */}
      <div className="space-y-2">
        <h2 className="font-serif italic text-2xl font-normal text-foreground">
          The signature.
        </h2>
        <p className="text-sm leading-6 text-muted-foreground max-w-prose">
          Enable in-studio card payments to charge clients, route artist commissions,
          and file 1099s. Powered by Stripe Connect Express.
        </p>
      </div>

      {/* Feature unlock cards */}
      <div className="grid gap-4 sm:grid-cols-3">
        {UNLOCK_ITEMS.map((item) => (
          <div
            key={item.title}
            className={cn(
              'rounded-xl border border-border/60 bg-card p-5 space-y-3',
              'shadow-[var(--shadow-soft)]',
            )}
          >
            <div className="flex items-center gap-2.5">
              <item.icon className="size-4 shrink-0 text-muted-foreground" aria-hidden="true" />
              <p className="text-[13px] font-semibold text-foreground leading-snug">
                {item.title}
              </p>
            </div>
            <p className="text-xs leading-5 text-muted-foreground">
              {item.description}
            </p>
          </div>
        ))}
      </div>

      {/* CTA */}
      <div className="flex items-center gap-4">
        <Button
          onClick={() => setModalOpen(true)}
          disabled={busy}
          className="gap-2"
          size="lg"
        >
          {busy ? (
            <>
              <Loader2 className="size-4 animate-spin" aria-hidden="true" />
              Connecting to Stripe
            </>
          ) : (
            'Enable in-studio payments'
          )}
        </Button>
        <p className="text-xs text-muted-foreground">
          You will be redirected to Stripe to verify your business.
        </p>
      </div>

      {/* Country confirmation dialog */}
      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="font-serif italic text-xl font-normal text-foreground">
              Confirm your studio&rsquo;s country.
            </DialogTitle>
          </DialogHeader>

          <p className="text-sm leading-6 text-muted-foreground">
            Stripe sets your account country at creation. We can&rsquo;t change it later.
          </p>

          <div className="space-y-1.5">
            <label
              htmlFor="country-select"
              className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground"
            >
              Studio country
            </label>
            <select
              id="country-select"
              value={selectedCountry}
              onChange={(e) => setSelectedCountry(e.target.value)}
              className={cn(
                'w-full rounded-lg border border-border/60 bg-card px-3 py-2',
                'text-sm text-foreground',
                'focus:outline-none focus:ring-2 focus:ring-foreground/20',
              )}
            >
              {COUNTRY_OPTIONS.map((opt) => (
                <option key={opt.value} value={opt.value}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>

          <DialogFooter className="gap-2 sm:gap-2">
            <Button
              variant="outline"
              onClick={() => setModalOpen(false)}
              disabled={busy}
            >
              Cancel
            </Button>
            <Button
              onClick={() => {
                setModalOpen(false)
                void handleEnable(selectedCountry)
              }}
              disabled={busy}
              className="gap-2"
            >
              {busy ? (
                <>
                  <Loader2 className="size-4 animate-spin" aria-hidden="true" />
                  Connecting
                </>
              ) : (
                'Continue to Stripe'
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

